import{_ as e,o as i,c as t,ag as n}from"./chunks/framework.D5hoimZQ.js";const u=JSON.parse('{"title":"科学日报 · 2026-11-02（生物医学 · 21 三体肺发育 / 癌症翻译重编程）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/biomedicine/science-daily-2026-11-02-biomed.md","filePath":"topics/biomedicine/science-daily-2026-11-02-biomed.md"}'),s={name:"topics/biomedicine/science-daily-2026-11-02-biomed.md"};function r(l,o,c,d,a,g){return i(),t("div",null,[...o[0]||(o[0]=[n('<h1 id="科学日报-·-2026-11-02-生物医学-·-21-三体肺发育-癌症翻译重编程" tabindex="-1">科学日报 · 2026-11-02（生物医学 · 21 三体肺发育 / 癌症翻译重编程） <a class="header-anchor" href="#科学日报-·-2026-11-02-生物医学-·-21-三体肺发育-癌症翻译重编程" aria-label="Permalink to &quot;科学日报 · 2026-11-02（生物医学 · 21 三体肺发育 / 癌症翻译重编程）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-11-02.md</code> — 第52期 ｜ 科学板块（2 篇） 落盘说明：文件名带 <code>-biomed</code> 后缀，避免与其它主题同日同名文件互引产生伪边（见 <code>topics/ai-brain/auto-link-quality-fixes.md</code>）。</p></blockquote><hr><h2 id="科学日报-2026-11-02-生物医学-·-1-2-21-三体的肺为什么长不好——i-型干扰素过度信号提前驱动「远端化」" tabindex="-1">科学日报 2026-11-02（生物医学 · 1/2）：21 三体的肺为什么长不好——I 型干扰素过度信号提前驱动「远端化」 <a class="header-anchor" href="#科学日报-2026-11-02-生物医学-·-1-2-21-三体的肺为什么长不好——i-型干扰素过度信号提前驱动「远端化」" aria-label="Permalink to &quot;科学日报 2026-11-02（生物医学 · 1/2）：21 三体的肺为什么长不好——I 型干扰素过度信号提前驱动「远端化」&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-11-02.md</code> ｜ DOI: 10.1038/s41467-026-79210-4 ｜ Nature Communications (2026)</p></blockquote><ul><li>问题：肺部并发症是<strong>唐氏综合征（21 三体，T21）<strong>患儿致病与致死的主要原因，此前已发现 <strong>T21 相关先天性肺异常</strong>，但</strong>机制不明</strong>；同时 T21 多种组织中 <strong>I 型干扰素（IFN-I）信号持续过度激活</strong>。</li><li>方法：在<strong>正在发育的人肺组织</strong>里考察 <strong>IFN-I 过度激活与抑制</strong>的效应：<strong>单细胞 RNA 测序</strong> + <strong>谱系特异的细胞共培养</strong>。</li><li>结果（实测）： <ul><li>对<strong>组织外植体施加 IFN 处理</strong>，在很大程度上<strong>重演了 T21 肺中上皮分化改变</strong>相关的转录变化；</li><li>谱系特异共培养进一步证实，<strong>间充质驱动的 IFN-I 过度激活</strong>促进<strong>上皮芽重塑、改变祖细胞身份</strong>，并提示诱导了 <strong>AT2 样程序（提前远端化，premature distalization）</strong>；</li><li><strong>IFN-I 对 T21 相关肺病理既必要又充分</strong>，并提供了一个<strong>可用于治疗发现的人肺模型系统</strong>。</li></ul></li><li>洞察（对本库 <code>biomedicine</code>）： <ol><li><strong>「慢性低度炎症信号能改写发育程序」</strong> —— 判据：<strong>当某综合征出现器官发育异常时，先查是否存在『持续激活的炎症/干扰素通路』在改写分化轨迹</strong>，而不是只看致病基因本身。</li><li><strong>「必要且充分 = 单一可干预靶点」</strong> —— 判据：<strong>在机制未明的发育病里，优先锁定那个『需要且足以复现表型』的通路</strong>（此处即 IFN-I）。</li></ol></li></ul><hr><h2 id="科学日报-2026-11-02-生物医学-·-2-2-甲基化的-eef1a「挑密码子翻译」——选择性解码塑造致癌蛋白质组、驱动-kras-抑制剂耐药" tabindex="-1">科学日报 2026-11-02（生物医学 · 2/2）：甲基化的 eEF1A「挑密码子翻译」——选择性解码塑造致癌蛋白质组、驱动 KRAS 抑制剂耐药 <a class="header-anchor" href="#科学日报-2026-11-02-生物医学-·-2-2-甲基化的-eef1a「挑密码子翻译」——选择性解码塑造致癌蛋白质组、驱动-kras-抑制剂耐药" aria-label="Permalink to &quot;科学日报 2026-11-02（生物医学 · 2/2）：甲基化的 eEF1A「挑密码子翻译」——选择性解码塑造致癌蛋白质组、驱动 KRAS 抑制剂耐药&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-11-02.md</code> ｜ DOI: 10.1038/s41556-026-02085-6 ｜ Nature Cell Biology (2026)</p></blockquote><ul><li>问题：mRNA 解码效率影响蛋白合成，但<strong>翻译延伸机器是否内含『选择性调节密码子解码、从而塑造蛋白质组』的机制</strong>尚不清楚。</li><li>方法：考察 <strong>METTL13 催化的延伸因子 eEF1A 第 55 位赖氨酸二甲基化（eEF1A^K55me2）</strong> 对<strong>密码子解码</strong>的影响；用<strong>蛋白质组谱 + 单分子成像</strong>追踪。</li><li>结果（实测）： <ul><li>eEF1A^K55me2 <strong>增强特定密码子的解码</strong>，优先提高<strong>促癌蛋白</strong>的合成，促进<strong>肿瘤发生与靶向治疗耐药</strong>；</li><li>它尤其提高<strong>摆位碱基配对较弱的稀有密码子</strong>的解码效率；</li><li>敲低 <strong>METTL13</strong> 降低了富含该依赖密码子的致癌 mRNA（包括 <strong>KRAS</strong>）的翻译；把这些密码子<strong>同义改写</strong>为不依赖该修饰的版本可<strong>逆转</strong>这一效应；</li><li>在<strong>对 KRAS G12C 抑制剂（sotorasib）耐药的肺腺癌</strong>模型中，<strong>METTL13 缺失</strong>抑制肿瘤生长、<strong>减轻耐药</strong>并<strong>显著延长生存</strong>。</li></ul></li><li>洞察（对本库 <code>biomedicine</code>）： <ol><li><strong>「翻译层是致癌蛋白质组的第二个控制面」</strong> —— 判据：<strong>当 mRNA 水平解释不了蛋白丰度差异时，去查翻译延伸层面的密码子选择性</strong>，而不是只做转录组。</li><li><strong>「耐药可以发生在翻译机器上」</strong> —— 判据：<strong>面对靶向药耐药，除了查靶点二次突变，也要查『翻译重编程』这类非突变通路</strong>。</li></ol></li></ul><hr><blockquote><p>📎 关联主题：<code>topics/biomedicine/index.md</code> ｜ 第52期 科学板块</p></blockquote><p>关键词：科学日报第52期、21三体 trisomy 21、唐氏综合征、I 型干扰素 IFN-I、人肺发育、单细胞 RNA 测序、上皮芽重塑、祖细胞身份、AT2 样程序、提前远端化 premature distalization、必要且充分、人肺模型系统、METTL13、eEF1A K55me2、密码子解码、稀有密码子、摆位碱基配对、KRAS、sotorasib 耐药、肺腺癌、翻译重编程、同义改写</p><p>关联：<code>topics/biomedicine/index.md</code>、<code>topics/biomedicine/science-daily-2026-10-31-biomed.md</code>、<code>topics/biomedicine/science-daily-2026-10-30-biomed.md</code>、<code>topics/biomedicine/science-daily-2026-10-29-biomed.md</code>、<code>topics/neuroscience/index.md</code></p>',14)])])}const b=e(s,[["render",r]]);export{u as __pageData,b as default};
